local Workspace = game:GetService(S(130))
local function getCurrentPlot()
    local player = Players.LocalPlayer
    local mineWorld = Workspace:FindFirstChild(S(269))
    local plots = mineWorld and mineWorld:FindFirstChild(S(251))
    if not plots then
        return nil
    end
    for _, plot in ipairs(plots:GetChildren()) do
        if plot:GetAttribute(S(306)) == player.UserId then
            return plot
        end
    end
    return nil
end
return getCurrentPlot
end
modules[S(281)] = function()
local function getPlotParts(plot)
    return {
        Holders = plot:FindFirstChild(S(28)),
        Nodes = plot:FindFirstChild(S(124)),
        Chest = plot:FindFirstChild(S(246)),
        Zones = plot:FindFirstChild(S(61)),
        Crew = plot:FindFirstChild(S(271)),
        Loot = plot:FindFirstChild(S(279)),
        PlotIndex = plot:GetAttribute(S(143)),
        ChestCapacity = plot:GetAttribute(S(19)),
    }
end
return getPlotParts
end
